"""Exact post-RC8 feedback transaction insertion; no neural-rule edits."""
import hashlib

BASE_SHA256 = {'src/scarx/hybrid/engine.py': '630763d4a14b4ac30e235b3daf1d58e1d8c8d524b9850cdee7156581123a6546', 'src/scarx/hybrid/store.py': '0314f575475027cb11dd15e484e38d3c10baf72bddfc0a8d4ccaaed677974385'}
BLOCKS = {'src/scarx/hybrid/engine.py': [('    def feedback(\n', "    def feedback_once(\n        self, request_id, identifier, text=None, helpful=None, positive_ids=(), negative_ids=()\n    ):\n        if (not isinstance(positive_ids, (list, tuple)) or not isinstance(negative_ids, (list, tuple))\n                or len(positive_ids) + len(negative_ids) > 128\n                or any(not isinstance(x, str) or not 1 <= len(x) <= 160\n                       for x in (*positive_ids, *negative_ids))):\n            raise ValueError('Feedback candidate labels must be a bounded ID list')\n        positive_ids, negative_ids = list(positive_ids), list(negative_ids)\n        if len(set(positive_ids)) != len(positive_ids) or len(set(negative_ids)) != len(negative_ids):\n            raise ValueError('Duplicate feedback candidate labels')\n        request = {'identifier': identifier, 'text': text, 'helpful': helpful,\n                   'positive_ids': positive_ids, 'negative_ids': negative_ids}\n        fingerprint = hashlib.sha256(encode(request).encode()).hexdigest()\n        # Lock order matches step/incident handling. In particular, an observer\n        # must not hold incidents.lock waiting for Store.lock while this callback\n        # holds Store.lock and attempts to finish the incident.\n        with self.lock, self.incidents.lock:\n            previous = self.model.dumps(self.state)\n            def apply():\n                result = self.feedback(identifier, text, helpful, positive_ids, negative_ids)\n                learning = result.get('learning') or []\n                if isinstance(learning, dict):\n                    learning = [learning]\n                if any(row.get('persistence_failed') for row in learning):\n                    raise OSError('Feedback update failed to persist; retry the same request')\n                return result\n            try:\n                return self.store.atomic_feedback(request_id, fingerprint, apply)\n            except Exception:\n                self.model, self.state = self._decode_snapshot(previous)\n                raise\n\n    def feedback(\n")], 'src/scarx/hybrid/store.py': [('class Store:\n', 'class _DeferredConnection:\n    """Defer nested connection contexts to one outer feedback transaction.\n\n    Used only while Store.lock is held. SQLite connections normally commit at\n    every nested `with connection`, so an ordinary outer context is insufficient.\n    """\n    def __init__(self, connection):\n        self.connection = connection\n\n    def __getattr__(self, name):\n        return getattr(self.connection, name)\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *exc):\n        return False\n\n\nclass Store:\n'), ('    def list(', "    def atomic_feedback(self, request_id, fingerprint, callback):\n        if (not isinstance(request_id, str) or not 1 <= len(request_id) <= 128\n                or any(not (c.isalnum() or c in '-_.') for c in request_id)\n                or not isinstance(fingerprint, str) or len(fingerprint) != 64\n                or any(c not in '0123456789abcdef' for c in fingerprint)):\n            raise ValueError('Invalid feedback retry identity')\n        key = hashlib.sha256(request_id.encode()).hexdigest()\n        with self.lock:\n            cached = self.get('feedback_receipt', key)\n            if cached is not None:\n                if cached.get('fingerprint') != fingerprint:\n                    raise ValueError('Feedback retry identity was reused with different content')\n                return cached['response']\n            connection = self.db\n            if isinstance(connection, _DeferredConnection) or connection.in_transaction:\n                raise RuntimeError('Feedback needs its own outer transaction')\n            self.db = _DeferredConnection(connection)\n            try:\n                with connection:\n                    result = callback()\n                    self.put('feedback_receipt', key,\n                             {'fingerprint': fingerprint, 'response': result})\n                return result\n            finally:\n                self.db = connection\n\n    def list(")]}

def patch_bytes(target, raw):
    if target not in BASE_SHA256 or hashlib.sha256(raw).hexdigest() != BASE_SHA256[target]:
        raise ValueError('Atomic feedback patch requires exact RC8 source')
    newline = '\r\n' if b'\r\n' in raw else '\n'
    text = raw.decode('utf-8')
    for old, new in BLOCKS[target]:
        old, new = (old.replace('\n', newline), new.replace('\n', newline))
        if text.count(old) != 1:
            raise ValueError('Atomic feedback insertion anchor changed')
        text = text.replace(old, new, 1)
    return text.encode('utf-8')
